def full_adder(a, b, carry_in):
    partial = a ^ b
    return (partial ^ carry_in, (a & b) | (carry_in & partial))

def add(a, b):
    out = []
    carry = 0
    for x, y in zip(a, b):
        bit, carry = full_adder(x, y, carry)
        out.append(bit)
    return (out, carry)
